      "code": "import { webcrypto } from 'crypto';\n\nconst crypto = webcrypto || globalThis.crypto;\n\n// Helper to convert Uint8Array bytes to hex string\nfunction bytesToHex(bytes) {\n  return Array.from(bytes)\n    .map(b => b.toString(16).padStart(2, '0'))\n    .join('');\n}\n\n// Helper to convert hex string to Uint8Array bytes\nfunction hexToBytes(hex) {\n  if (hex.length % 2 !== 0) {\n    throw new Error('Invalid hex string length');\n  }\n  const bytes = new Uint8Array(hex.length / 2);\n  for (let i = 0; i < bytes.length; i++) {\n    bytes[i] = parseInt(hex.substring(i * 2, i * 2 + 2), 16);\n  }\n  return bytes;\n}\n\n/**\n * Generate a SHA-256 hash of a string.\n * @param {string} text - The input text.\n * @returns {Promise<string>} Hex encoded hash.\n */\nexport async function sha256(text) {\n  const encoder = new TextEncoder();\n  const data = encoder.encode(text);\n  const hashBuffer = await crypto.subtle.digest('SHA-256', data);\n  return bytesToHex(new Uint8Array(hashBuffer));\n}\n\n/**\n * Derive a secure key or hash using PBKDF2 (similar to bcrypt for password storage).\n * @param {string} password - The plain-text password.\n * @param {string} [salt] - The salt string (hex formatted). If omitted, a random 16-byte salt is generated.\n * @param {number} [iterations=100000] - Hardness factor.\n * @returns {Promise<{ hash: string, salt: string }>} Hex encoded hash and salt.\n */\nexport async function hashPassword(password, salt = null, iterations = 100000) {\n  const encoder = new TextEncoder();\n  const passwordBytes = encoder.encode(password);\n  \n  let saltBytes;\n  if (salt) {\n    saltBytes = hexToBytes(salt);\n  } else {\n    saltBytes = crypto.getRandomValues(new Uint8Array(16));\n  }\n\n  const baseKey = await crypto.subtle.importKey(\n    'raw',\n    passwordBytes,\n    'PBKDF2',\n    false,\n    ['deriveBits', 'deriveKey']\n  );\n\n  const derivedBits = await crypto.subtle.deriveBits(\n    {\n      name: 'PBKDF2',\n      salt: saltBytes,\n      iterations,\n      hash: 'SHA-256'\n    },\n    baseKey,\n    256 // length in bits\n  );\n\n  return {\n    hash: bytesToHex(new Uint8Array(derivedBits)),\n    salt: bytesToHex(saltBytes)\n  };\n}\n\n/**\n * Verify a password against a PBKDF2 hash and salt.\n * @param {string} password - The plain-text password.\n * @param {string} hash - The stored hash to compare.\n * @param {string} salt - The stored salt.\n * @param {number} [iterations=100000] - Iteration count.\n * @returns {Promise<boolean>} True if password matches.\n */\nexport async function verifyPassword(password, hash, salt, iterations = 100000) {\n  const result = await hashPassword(password, salt, iterations);\n  return result.hash === hash;\n}\n",
      "readme": "# Lego Block: `crypto/hash`\n\nCryptographic hashing (SHA-256) and password verification helper (PBKDF2) using native Web Crypto API.\n\n> [!NOTE]\n> **AI Agent Context:** Use this block when hashing strings, generating cryptographic check-sums, or securely storing and verifying user passwords without bringing in heavy native libraries like bcrypt.\n\n---\n\n## Installation\n\nTo copy this block directly into your project codebase, run the following CLI command:\n```bash\nnpx lego-cli add crypto/hash\n```\n\n---\n\n## API Specifications\n\n### Parameters\n\n| Parameter | Type | Required | Default | Description |\n|---|---|---|---|---|\n| `password` | `string` | ⚠️ Yes | *-* | The plaintext password/string to hash. |\n| `salt` | `string` | No | *-* | Optional hex salt. Will be randomly generated if not provided. |\n| `iterations` | `number` | No | `100000` | The PBKDF2 iteration strength parameter. |\n\n\n---\n\n## System Compatibility\n\n| Runtime Environment | Status |\n|---|---|\n| **Browsers (Chrome, Safari, Firefox, Edge)** | ✅ Supported |\n| **Node.js** | ✅ Supported |\n| **Deno** | ✅ Supported |\n| **Bun** | ✅ Supported |\n\n---\n\n## Computational Complexity\n\n* **Time Complexity:** `O(N) input bytes digested`\n* **Space Complexity:** `O(1) fixed-size output digest`\n\n---\n\n## Production Usage Example\n\nRefer to `index.js` inside this folder for full API details.\n",
